create table if not exists platform_decisions(id uuid primary key default gen_random_uuid(),organization_id uuid not null,project_id uuid,type text not null,title text not null,risk text not null,confidence numeric not null,status text not null,recommendation text not null,explanation text not null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),executed_at timestamptz);
create table if not exists platform_decision_approvals(id uuid primary key default gen_random_uuid(),decision_id uuid not null references platform_decisions(id) on delete cascade,organization_id uuid not null,status text not null default 'PENDING',requested_at timestamptz not null default now(),reviewed_at timestamptz,reviewer_id uuid,comment text);
create table if not exists platform_decision_outcomes(id uuid primary key default gen_random_uuid(),decision_id uuid not null references platform_decisions(id) on delete cascade,success boolean not null,impact numeric not null,notes text,measured_at timestamptz not null default now());
create index if not exists idx_platform_decisions_org_created on platform_decisions(organization_id,created_at desc);
create index if not exists idx_platform_decision_approvals_status on platform_decision_approvals(status,requested_at);
create index if not exists idx_platform_decision_outcomes_decision on platform_decision_outcomes(decision_id,measured_at desc);